import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    names = z.namelist()

    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall(M + 'si'):
            text = ''.join(t.text or '' for t in si.iter(M + 't'))
            shared.append(text)

    wbroot = ET.fromstring(z.read('xl/workbook.xml'))
    sheet_list = []
    for s in wbroot.find(M + 'sheets').findall(M + 'sheet'):
        sheet_list.append((s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))

    relroot = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rels = {}
    for rel in relroot:
        rels[rel.get('Id')] = rel.get('Target')

    def resolve(target):
        if target.startswith('/'):
            return target.lstrip('/')
        if not target.startswith('xl/'):
            return 'xl/' + target
        return target

    print("CELL DATA:")
    for name, rid in sheet_list:
        target = resolve(rels[rid])
        sroot = ET.fromstring(z.read(target))
        print(f"=== Sheet: {name} ===")
        for row in sroot.find(M + 'sheetData').findall(M + 'row'):
            for c in row.findall(M + 'c'):
                ref = c.get('r')
                t = c.get('t')
                v = c.find(M + 'v')
                f = c.find(M + 'f')
                val = None
                if f is not None:
                    val = '=' + (f.text or '')
                elif v is not None:
                    val = v.text
                    if t == 's':
                        val = shared[int(val)]
                    elif t == 'b':
                        val = val == '1'
                    elif t == 'inlineStr':
                        is_ = c.find(M + 'is')
                        val = ''.join(tt.text or '' for tt in is_.iter(M + 't'))
                print(f"  {ref}: {val!r}")
        print()

import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

expenses = {}   # category -> subtotal
income = {}
for row in root.find(M + 'sheetData').findall(M + 'row'):
    cells = {c.get('r'): c for c in row.findall(M + 'c')}
    a = cells.get('A' + row.get('r'))
    text = ''
    if a is not None and a.get('t') == 'inlineStr':
        text = ''.join(t.text or '' for t in a.find(M + 'is').iter(M + 't'))

    if 11 <= int(row.get('r')) <= 22:
        c = cells.get('C' + row.get('r'))
        if c is not None:
            v = c.find(M + 'v')
            if v is not None:
                expenses.setdefault(text, 0.0)
                expenses[text] += float(v.text)
    elif 4 <= int(row.get('r')) <= 7:
        b = cells.get('B' + row.get('r'))
        if b is not None:
            v = b.find(M + 'v')
            if v is not None:
                income[text] = float(v.text)

total_exp = sum(expenses.values())
total_inc = sum(income.values())
print("INCOME:")
for k, v in income.items():
    print(f"  {k}: {v}")
print(f"  Total Income (matches B8=SUM(B4:B7)): {total_inc}")

print("\nEXPENSES BY CATEGORY:")
for k, v in expenses.items():
    print(f"  {k}: {v}")
print(f"  TOTAL EXPENSES: {total_exp}")
print(f"  (check C23=SUM(C11:C22): 1500+200+150+350+150+100+500+200+50+100+500+400 = {1500+200+150+350+150+100+500+200+50+100+500+400})")

print("\nNOTE: B25 formula is '=B8-C22' ->", total_inc - 400, "but correct balance would be B8-C23 =", total_inc - total_exp)

